int comedi_dev_ioctl_get_devinfo(struct comedi_device *dev, struct comedi_devinfo __user *arg, struct file *file)
{
    struct comedi_devinfo info;
    int read_subdev = -1;
    int write_subdev = -1;
    int i;

    info.version = dev->version_code;
    info.n_subdevices = dev->n_subdevices;

    strncpy(info.driver_name, dev->driver->driver_name, COMEDI_MAX_DRIVER_NAME);
    info.driver_name[COMEDI_MAX_DRIVER_NAME] = '\0';

    strncpy(info.board_name, dev->board_name, COMEDI_MAX_BOARD_NAME);
    info.board_name[COMEDI_MAX_BOARD_NAME] = '\0';

    for (i = 0; i < dev->n_subdevices; ++i) {
        struct comedi_subdevice *s = &dev->subdevices[i];
        if (s->type == COMEDI_SUBD_AI) {
            read_subdev = i;
        } else if (s->type == COMEDI_SUBD_AO) {
            write_subdev = i;
        }
    }

    info.read_subdev = read_subdev;
    info.write_subdev = write_subdev;

    if (copy_to_user(arg, &info, sizeof(info)))
        return -EFAULT;

    return 0;
}

int comedi_ioctl_devinfo(struct comedi_device *dev, struct comedi_devinfo __user *arg, struct file *file)
{
	struct comedi_devinfo info;
	int rsubdev, wsubdev;
	int i;

	info.version = dev->version_code;
	info.nsubdev = dev->nsubdev;
	memset(info.subdevs, 0, sizeof(info.subdevs));
	for (i = 0; i < dev->nsubdev; i++)
		info.subdevs[i] = dev->subdevices[i].type;
	strncpy(info.driver_name, dev->driver->driver_name, COMEDI_NAMELEN);
	strncpy(info.board_name, dev->board_name, COMEDI_NAMELEN);

	rsubdev = -1;
	wsubdev = -1;
	for (i = 0; i < dev->nsubdev; i++) {
		if (dev->subdevices[i].subdev_flags & SDF_READ)
			rsubdev = i;
		if (dev->subdevices[i].subdev_flags & SDF_WRITE)
			wsubdev = i;
	}
	info.read_subdev = rsubdev;
	info.write_subdev = wsubdev;

	if (copy_to_user(arg, &info, sizeof(info)))
		return -EFAULT;

	return 0;
}

